```sql
SELECT name FROM circuits WHERE circuitRef = 'Marina Bay Street Circuit';
```

```sql
SELECT s.full_name AS race FROM superhero s JOIN superpower sp ON s.id = sp.power_id;
```

```sql
SELECT CAST(SUM(CASE WHEN p.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) AS INTEGER) * 100.0 / COUNT(p.id) as percentage;
```

```sql
SELECT CAST(ROUND(SUM(CASE WHEN language = 'French' AND power IS NULL OR power = '*' THEN 1 ELSE 0 END) AS REAL) / COUNT(*) * 100, 2) as percentage;
```
